export const glossary = [
  // === A ===
  { term: "Abridging", definition: "Reducing or limiting. When the 1st Amendment says Congress can't pass laws 'abridging' free speech, it means they can't limit or reduce your speech rights." },
  { term: "Acquittal", definition: "A verdict of not guilty. Once acquitted, double jeopardy prevents being tried again for the same crime." },
  { term: "Actual Malice", definition: "The legal standard for defamation of public officials. To win a lawsuit, the official must prove the statement was made knowing it was false or with reckless disregard for the truth. Established in New York Times v. Sullivan." },
  { term: "Adherence", definition: "In the context of treason, 'adhering to' enemies means giving them loyalty or support. The Constitution defines treason as levying war against the U.S. or adhering to its enemies." },
  { term: "Administrative Search", definition: "A government inspection of property for regulatory purposes, like housing code enforcement. Even routine inspections of homes require consent or a warrant, though the standard is lower than for criminal searches." },
  { term: "Affirm", definition: "When a higher court agrees with a lower court's decision and lets it stand. The opposite of 'reverse.'" },
  { term: "Aid and Comfort", definition: "Help or support given to an enemy. Under the Constitution, giving 'aid and comfort' to enemies of the United States is part of the legal definition of treason." },
  { term: "Allegiance", definition: "Loyalty owed to a government or ruler. The Declaration of Independence declared the colonies 'absolved from all allegiance to the British Crown.'" },
  { term: "Amend", definition: "To formally change. The Constitution can be amended through a process requiring 2/3 of Congress and 3/4 of state legislatures." },
  { term: "Amendment", definition: "A formal change or addition to the Constitution. There are 27 amendments. The first 10 are called the Bill of Rights." },
  { term: "Amicus Curiae", definition: "Latin for 'friend of the court.' A person or organization not involved in a case who submits a brief offering information or arguments to help the court decide. Common in Supreme Court cases." },
  { term: "Anti-Commandeering Doctrine", definition: "The principle that the federal government cannot force state or local officials to enforce federal laws. States can choose to cooperate but cannot be compelled to." },
  { term: "Appellate Jurisdiction", definition: "The power of a higher court to review decisions made by lower courts. The Supreme Court mostly operates this way." },
  { term: "Apportionment", definition: "Dividing something proportionally. House seats are apportioned among states based on population counts from the census." },
  { term: "Arbitration", definition: "A private process where disputes are resolved by a neutral third party instead of a court. Many contracts require mandatory arbitration, meaning you give up your right to a jury trial." },
  { term: "Arms", definition: "Weapons. The 2nd Amendment protects the right to keep and bear arms. Courts have debated what types of weapons this covers." },
  { term: "Arraignment", definition: "A court hearing where a person accused of a crime is formally told what they are charged with and asked to plead guilty or not guilty." },
  { term: "Assent", definition: "Agreement or approval. The Declaration lists the King's refusal to give 'assent to laws,' meaning he blocked laws the colonists needed." },

  // === B ===
  { term: "Bail", definition: "Money paid to get released from jail while awaiting trial. The 8th Amendment says it can't be set excessively high." },
  { term: "Balancing Test", definition: "A method courts use to weigh competing interests. For example, balancing a government employee's free speech rights against the employer's need for efficient operations." },
  { term: "Bill of Attainder", definition: "A law that punishes a specific person or group without a trial. The Constitution explicitly bans these." },
  { term: "Bill of Rights", definition: "The first 10 amendments to the Constitution, ratified in 1791. These spell out your most fundamental personal rights against government interference." },
  { term: "Brief", definition: "A written legal argument submitted to a court. Lawyers file briefs to explain their position and cite relevant laws and cases." },
  { term: "Burden of Proof", definition: "The obligation to prove your case. In criminal trials, the prosecution bears the burden and must prove guilt 'beyond a reasonable doubt.' In civil cases, the standard is lower: 'preponderance of the evidence' (more likely than not)." },

  // === C ===
  { term: "Capital Crime", definition: "A crime punishable by death. The 5th Amendment requires a grand jury indictment for capital crimes." },
  { term: "Case Law", definition: "Law created by court decisions rather than by legislation. When judges interpret the Constitution or statutes, their rulings become case law that guides future decisions." },
  { term: "Censorship", definition: "When the government suppresses speech, press, or information. The 1st Amendment generally prohibits government censorship, especially 'prior restraint,' which means blocking publication before it happens." },
  { term: "Certiorari", definition: "An order from a higher court to review a lower court's decision. The Supreme Court grants 'cert' to cases it chooses to hear, typically about 70-80 per year out of thousands of requests." },
  { term: "Checks and Balances", definition: "The system where each branch of government can limit the others. Congress makes laws, the President can veto them, and courts can strike them down as unconstitutional." },
  { term: "Civil Asset Forfeiture", definition: "When the government seizes your property (cash, car, house) based on suspicion it was involved in a crime, without necessarily charging you with a crime. The property itself is 'charged,' and you must prove your innocence to get it back." },
  { term: "Civil Law", definition: "The area of law dealing with disputes between private parties (contracts, property, injuries) as opposed to criminal law. In civil cases, the penalty is usually money, not jail." },
  { term: "Civil Liberties", definition: "Individual freedoms that the government cannot take away, like free speech, religion, and the right to a fair trial." },
  { term: "Civil Rights", definition: "Rights that protect individuals from discrimination. The 14th Amendment's equal protection clause is the foundation of most civil rights law." },
  { term: "Class Action", definition: "A lawsuit filed by one or more people on behalf of a larger group who all suffered the same harm. For example, all customers overcharged by a company suing together." },
  { term: "Clause", definition: "A specific section or provision within a legal document. The Constitution contains many named clauses, like the Commerce Clause, the Supremacy Clause, and the Due Process Clause." },
  { term: "Coercion", definition: "Forcing someone to do something through threats, pressure, or intimidation. Confessions obtained through coercion are inadmissible in court, and government coercion of private companies to censor speech may violate the 1st Amendment." },
  { term: "Color of Law", definition: "Acting with the appearance of legal authority. When a police officer or government official violates your rights while on duty, they are acting 'under color of law,' which can be the basis for a federal civil rights lawsuit." },
  { term: "Commander in Chief", definition: "The President's role as the top authority over the military. The President commands the armed forces but cannot declare war, because only Congress can do that." },
  { term: "Commerce Clause", definition: "Article I, Section 8 gives Congress power to regulate trade between states. This has been interpreted very broadly to justify a wide range of federal laws." },
  { term: "Common Law", definition: "Law developed through court decisions over centuries rather than written by a legislature. Many legal principles in America come from English common law traditions." },
  { term: "Compelling Interest", definition: "A government purpose so important that it can justify restricting a fundamental right. To pass 'strict scrutiny,' the government must show a compelling interest and use the least restrictive means possible." },
  { term: "Compulsory Process", definition: "The power to force witnesses to appear in court and testify. The 6th Amendment guarantees defendants the right to compulsory process to bring witnesses in their favor." },
  { term: "Concurrent Powers", definition: "Powers shared by both federal and state governments, like the power to tax, build roads, and create courts." },
  { term: "Concurrence", definition: "A written opinion by a judge who agrees with the outcome of a case but for different reasons than the majority. Concurrences can influence how future courts interpret the law." },
  { term: "Confederation", definition: "A loose alliance of independent states. The United States was originally a confederation under the Articles of Confederation before the Constitution created a stronger federal government." },
  { term: "Confrontation Clause", definition: "The part of the 6th Amendment that gives you the right to face your accusers in court and cross-examine witnesses who testify against you. No secret witnesses allowed." },
  { term: "Consent Decree", definition: "A court-approved agreement to resolve a lawsuit. Often used when the government settles civil rights cases, where the defendant agrees to make changes without admitting wrongdoing." },
  { term: "Consent of the Governed", definition: "The idea that government's authority comes from the people agreeing to be governed. From the Declaration of Independence." },
  { term: "Construe", definition: "To interpret the meaning of a law or legal text. The 9th Amendment says listing certain rights 'shall not be construed' (interpreted) to deny other rights you have." },
  { term: "Content Neutrality", definition: "The principle that the government cannot favor or disfavor speech based on its message. A law banning all signs is content-neutral; a law banning only political signs is not." },
  { term: "Continuance", definition: "A postponement of a court proceeding to a later date. Too many continuances can violate the right to a speedy trial." },
  { term: "Conviction", definition: "A formal finding that a person is guilty of a crime. Can happen through a guilty verdict at trial or a guilty plea." },
  { term: "Corruption of Blood", definition: "An old punishment where the families of convicted traitors also lost their rights and property. The Constitution specifically bans this, meaning you can't be punished for a family member's crime." },
  { term: "Counsel", definition: "A lawyer. The 6th Amendment guarantees the right to 'assistance of counsel,' meaning you have the right to a lawyer in criminal cases, and if you can't afford one, the court must provide one for free." },
  { term: "Criminal Law", definition: "The area of law dealing with crimes against the state (theft, assault, murder). The government is always the prosecutor. Penalties can include fines, probation, or imprisonment." },
  { term: "Cross-Examine", definition: "To question a witness who was called by the other side. The 6th Amendment guarantees your right to cross-examine witnesses testifying against you." },
  { term: "Cruel and Unusual Punishment", definition: "Punishment that is barbaric, torturous, or grossly disproportionate to the crime. Banned by the 8th Amendment. What counts as 'cruel and unusual' evolves over time." },
  { term: "Custodial Interrogation", definition: "Police questioning of a person who is in custody (arrested or not free to leave). Miranda warnings must be given before custodial interrogation begins." },

  // === D ===
  { term: "Declaratory Judgment", definition: "A court ruling that states the rights of the parties without ordering any specific action. Used to clarify legal rights before a dispute escalates." },
  { term: "Defendant", definition: "The person or entity being accused in a legal case. In criminal cases, it is the person charged with a crime. In civil cases, it is the person being sued." },
  { term: "Delegate", definition: "To transfer power or authority to someone else. When Congress delegates lawmaking power to agencies, it raises questions about whether unelected officials should make rules that affect your life." },
  { term: "Deliberation", definition: "The process of careful discussion and consideration. A jury deliberates in private to reach a verdict after hearing all the evidence." },
  { term: "Deposition", definition: "A witness's sworn out-of-court testimony, taken before trial as part of the discovery process. The witness answers questions under oath and a transcript is made." },
  { term: "Despotism", definition: "Absolute, tyrannical power. The Declaration of Independence says that when government 'evinces a design to reduce them under absolute despotism,' the people have the right to overthrow it." },
  { term: "Detained", definition: "Held by the government but not formally arrested or charged. Immigration detainees, for example, may be held for extended periods. The Constitution limits how long you can be detained without charges." },
  { term: "Dicta", definition: "Comments in a court opinion that are not essential to the decision. Dicta are not binding on future courts but can influence how the law develops." },
  { term: "Discovery", definition: "The pre-trial process where each side in a lawsuit can obtain evidence from the other side, including documents, records, and testimony." },
  { term: "Disenfranchise", definition: "To take away someone's right to vote. Historically, Black Americans were disenfranchised through poll taxes, literacy tests, and other barriers. Felony disenfranchisement still affects millions today." },
  { term: "Disparage", definition: "To belittle or treat as unimportant. The 9th Amendment says listing certain rights 'shall not be construed to deny or disparage' other rights, meaning unlisted rights still matter." },
  { term: "Dissent", definition: "A written opinion by a judge who disagrees with the majority's decision. Dissents have no legal force but can influence future courts. Some famous dissents have later become the law." },
  { term: "Dissolve", definition: "To formally break apart or end. The Declaration speaks of dissolving 'political bands,' which meant ending the political relationship between the colonies and Britain." },
  { term: "Doctrine", definition: "A principle or set of principles established through court decisions. Examples include the 'incorporation doctrine' and the 'exclusionary rule.' Doctrines guide how courts interpret the law." },
  { term: "Domestic Tranquility", definition: "Peace within the country. The Constitution's Preamble lists 'insure domestic tranquility' (keeping the peace at home) as one of the government's core purposes." },
  { term: "Double Jeopardy", definition: "Being tried twice for the same crime. The 5th Amendment prohibits this. However, state and federal governments are considered separate 'sovereigns,' so both can prosecute you for the same act." },
  { term: "Dual Sovereignty", definition: "The principle that state and federal governments are separate legal authorities. Because of this, both a state and the federal government can prosecute you for the same act without violating double jeopardy." },
  { term: "Due Process", definition: "The government must follow fair procedures before taking your life, liberty, or property. There are two types: procedural (fair process) and substantive (fair laws)." },
  { term: "Duties", definition: "Taxes charged on goods, especially imports. The Constitution gives Congress the power to lay and collect duties." },

  // === E ===
  { term: "Elastic Clause", definition: "Another name for the Necessary and Proper Clause. It lets Congress pass laws 'necessary and proper' to carry out its powers, 'stretching' federal authority beyond what is explicitly listed." },
  { term: "Electoral College", definition: "The system used to elect the President. Each state gets electors equal to its number of representatives plus senators. A candidate needs 270 electoral votes to win." },
  { term: "Electors", definition: "People chosen to cast votes in the Electoral College. Each state has electors equal to its Congressional delegation. They are expected to vote as their state's voters directed, and most states can punish 'faithless electors' who don't." },
  { term: "Eminent Domain", definition: "The government's power to take private property for public use, but the 5th Amendment requires they pay you 'just compensation.'" },
  { term: "Emoluments", definition: "Payments, profits, or benefits received from a position. The Constitution prohibits federal officials from accepting emoluments from foreign governments without Congressional consent." },
  { term: "Endowed", definition: "Given or granted. The Declaration says people are 'endowed by their Creator with certain unalienable rights,' meaning these rights are built into being human, not given by government." },
  { term: "Enjoin", definition: "To order someone to do or stop doing something through a court order (injunction). A court might enjoin the government from enforcing an unconstitutional law." },
  { term: "Enumerated Powers", definition: "Powers specifically listed in the Constitution as belonging to Congress (Article I, Section 8). If it's not listed, the 10th Amendment says it belongs to states or the people." },
  { term: "Enumeration", definition: "A formal listing or counting. The Constitution uses this word two ways: counting the population for apportionment, and listing ('enumerating') specific rights. The 9th Amendment says rights aren't limited to those enumerated." },
  { term: "Equal Protection", definition: "The 14th Amendment requirement that states treat all people equally under the law. The basis for fighting discrimination." },
  { term: "Equity", definition: "A branch of law focused on fairness when regular legal remedies are inadequate. Courts of equity can issue injunctions or order specific actions, not just award money damages." },
  { term: "Establishment Clause", definition: "The part of the 1st Amendment that says government cannot create or favor an official religion." },
  { term: "Evinces", definition: "Shows or demonstrates clearly. The Declaration says when a 'long train of abuses evinces a design to reduce them under despotism,' meaning when a pattern clearly shows tyrannical intent, the people must act." },
  { term: "Ex Parte", definition: "Latin for 'from one side.' A legal proceeding where only one party is present. Also used in case names, like 'Ex parte Merryman,' meaning the case was brought by Merryman alone." },
  { term: "Ex Post Facto Law", definition: "A law that makes something illegal after you already did it, then tries to punish you. The Constitution bans these." },
  { term: "Excessive Fines", definition: "Financial penalties that are disproportionate to the offense. The 8th Amendment prohibits excessive fines, which has been applied to limit civil asset forfeiture." },
  { term: "Exclusionary Rule", definition: "Evidence obtained through unconstitutional searches (violating the 4th Amendment) generally cannot be used against you in court." },
  { term: "Executive Order", definition: "A directive from the President to federal agencies. Has the force of law but doesn't go through Congress. Can be controversial when used to make major policy." },
  { term: "Executive Privilege", definition: "The claimed right of the President to keep certain communications confidential. Not mentioned in the Constitution but recognized by courts in limited form." },
  { term: "Exigent Circumstances", definition: "Emergency situations that allow police to act without a warrant. Examples include someone screaming for help inside a home or evidence about to be destroyed." },
  { term: "Extradition", definition: "The process of transferring a person accused of a crime from one state (or country) to another to face charges. The Constitution requires states to return fugitives to the state where they are charged." },

  // === F ===
  { term: "Faithless Elector", definition: "A member of the Electoral College who votes for someone other than the candidate they pledged to support. Most states can fine or replace faithless electors." },
  { term: "Federalism", definition: "The division of power between the federal government and state governments. Each has its own sphere of authority." },
  { term: "Felony", definition: "A serious crime punishable by more than one year in prison. Examples include murder, robbery, and drug trafficking. Contrasted with misdemeanors, which are less serious offenses." },
  { term: "Forfeiture", definition: "The loss of property as a penalty. Civil asset forfeiture lets the government take property suspected of being connected to a crime, often without a criminal conviction." },
  { term: "Free Exercise Clause", definition: "The part of the 1st Amendment that says government cannot prohibit you from practicing your religion." },
  { term: "Full Faith and Credit", definition: "The constitutional requirement that each state honor the laws, records, and court decisions of every other state. Your marriage, driver's license, and court judgments are valid across state lines." },

  // === G ===
  { term: "General Welfare", definition: "The well-being of the public as a whole. The Preamble lists 'promote the general welfare' as a purpose of government. Congress can tax and spend to promote it." },
  { term: "Gerrymandering", definition: "Drawing electoral district boundaries to give one political party an unfair advantage. Named after Governor Elbridge Gerry, whose 1812 redistricting map included a district shaped like a salamander." },
  { term: "Good Faith", definition: "Honest intent without knowledge of wrongdoing. A 'good faith exception' to the exclusionary rule allows evidence to be used if police reasonably believed their search was legal." },
  { term: "Grand Jury", definition: "A group of citizens who decide whether there's enough evidence to formally charge someone with a serious crime. Required by the 5th Amendment for federal cases." },
  { term: "Grievance", definition: "A complaint or objection. The 1st Amendment protects your right to 'petition the government for a redress of grievances,' which means to formally complain and demand that wrongs be fixed." },

  // === H ===
  { term: "Habeas Corpus", definition: "Latin for 'produce the body.' Your right to go before a judge and demand the government prove they have legal authority to hold you. The most fundamental protection against unlawful imprisonment." },
  { term: "Hearsay", definition: "An out-of-court statement offered as evidence in a trial. Generally not admissible because the person who made the statement isn't present to be cross-examined." },
  { term: "Heckler's Veto", definition: "When the government silences a speaker because the audience is hostile to their message. Courts have ruled the government cannot punish speakers for the reactions of their audience." },

  // === I ===
  { term: "Immunity", definition: "Legal protection from being sued or prosecuted. Types include sovereign immunity (government can't be sued), qualified immunity (protects officials from personal liability), and diplomatic immunity." },
  { term: "Impeachment", definition: "The process of formally charging a federal official with misconduct. The House impeaches (charges), the Senate tries (convicts or acquits). Requires 2/3 of the Senate to remove from office." },
  { term: "Imposts", definition: "Taxes or duties on imported goods. The Constitution gives Congress the power to collect imposts as a source of revenue." },
  { term: "Impel", definition: "To drive or push toward action. The Declaration says the colonists must 'declare the causes which impel them to the separation,' meaning they must explain what's pushing them to break away." },
  { term: "Inalienable", definition: "Cannot be taken away or given up. Also spelled 'unalienable.' The Declaration says your rights to life, liberty, and the pursuit of happiness are inalienable, and no government can remove them." },
  { term: "Incorporation Doctrine", definition: "The legal principle that most of the Bill of Rights applies to state governments through the 14th Amendment, not just the federal government." },
  { term: "Indictment", definition: "A formal accusation of a crime, issued by a grand jury. Required for serious federal crimes under the 5th Amendment." },
  { term: "Infamous Crime", definition: "A serious crime that carries significant punishment and social stigma. The 5th Amendment requires a grand jury indictment for 'capital or otherwise infamous' crimes." },
  { term: "Infringed", definition: "Violated or weakened. The 2nd Amendment says the right to bear arms 'shall not be infringed,' meaning it cannot be violated or undermined." },
  { term: "Injunction", definition: "A court order requiring someone to do or stop doing something. Courts can issue injunctions to block enforcement of unconstitutional laws." },
  { term: "Insurrection", definition: "A violent uprising against the government. The 14th Amendment bars anyone who participated in an insurrection from holding federal office." },
  { term: "Involuntary Servitude", definition: "Being forced to work against your will. Banned by the 13th Amendment except as punishment for a crime. Applies to situations like human trafficking and forced labor." },

  // === J ===
  { term: "Jeopardy", definition: "The risk of being convicted and punished for a crime. 'Double jeopardy' means being put at risk twice for the same offense, which the 5th Amendment prohibits." },
  { term: "Judicial Activism", definition: "When courts are seen as making policy decisions rather than just interpreting law. The term is often used by critics who disagree with a court's ruling." },
  { term: "Judicial Restraint", definition: "The philosophy that courts should avoid overturning laws unless clearly unconstitutional and should defer to elected branches when possible." },
  { term: "Judicial Review", definition: "The power of courts to declare laws unconstitutional. This power is not explicitly in the Constitution and was established by the Supreme Court in Marbury v. Madison (1803)." },
  { term: "Jurisdiction", definition: "The authority of a court to hear and decide a case. Federal courts have jurisdiction over federal law, constitutional questions, and disputes between states." },
  { term: "Jurisprudence", definition: "The theory and philosophy of law, or a body of court decisions on a subject. 'First Amendment jurisprudence' means all the court rulings that shape free speech law." },
  { term: "Just Compensation", definition: "Fair payment. The 5th Amendment requires the government to pay just compensation when it takes private property through eminent domain. Disputes often arise over what 'just' means." },

  // === L ===
  { term: "Lame Duck", definition: "An elected official serving out the remainder of their term after losing an election or choosing not to run again. The 20th Amendment shortened the lame duck period by moving Inauguration Day from March to January." },
  { term: "Letters of Marque and Reprisal", definition: "Government licenses authorizing private citizens to attack enemy ships during wartime. The Constitution gives Congress the power to issue these but bans states from doing so. No longer used." },
  { term: "Levy", definition: "To impose or collect. Congress has the power to 'levy' (collect) taxes, and to 'levy' (wage) war." },
  { term: "Libel", definition: "A false written statement that damages someone's reputation. For public officials to win a libel case, they must prove 'actual malice,' meaning that the writer knew the statement was false." },

  // === M ===
  { term: "Magistrate", definition: "A judicial officer with limited authority, often handling preliminary hearings, bail decisions, and issuing warrants. Not a full judge but exercises important judicial functions." },
  { term: "Major Questions Doctrine", definition: "The principle that federal agencies cannot make decisions of major economic or political significance without clear authorization from Congress. Established in West Virginia v. EPA (2022)." },
  { term: "Majority Opinion", definition: "The court's official decision, supported by more than half the judges. It sets binding precedent for lower courts. Also simply called 'the opinion of the court.'" },
  { term: "Mandamus", definition: "Latin for 'we command.' A court order directing a government official to perform a duty they are legally required to do. The case Marbury v. Madison involved a petition for a writ of mandamus." },
  { term: "Militia", definition: "A military force made up of ordinary citizens rather than professional soldiers. The 2nd Amendment references a 'well regulated militia.' Today, every state has a militia (the National Guard), and federal law defines the 'unorganized militia' as most male citizens aged 17-45." },
  { term: "Miranda Rights", definition: "Your right to remain silent and have an attorney present during police questioning. Police must inform you of these rights before custodial interrogation." },
  { term: "Misdemeanor", definition: "A less serious crime punishable by up to one year in jail, a fine, or both. Examples include petty theft, simple assault, and trespassing. More serious than an infraction but less than a felony." },
  { term: "Moot", definition: "No longer a live controversy. A case becomes 'moot' when the dispute has been resolved or the issue no longer matters, and courts generally won't rule on moot cases." },

  // === N ===
  { term: "Naturalization", definition: "The legal process of becoming a citizen if you were not born one. The 14th Amendment also grants citizenship to all persons born in the United States." },
  { term: "Necessary and Proper Clause", definition: "Article I, Section 8 lets Congress make any law 'necessary and proper' to carry out its listed powers. Also called the 'elastic clause' because it stretches federal power." },
  { term: "Nondelegation Doctrine", definition: "The principle that Congress cannot hand off its lawmaking power to agencies or the executive branch. Rarely enforced in modern times, but periodically raised as a check on regulatory agencies." },
  { term: "Notwithstanding", definition: "Despite or regardless of. When the Constitution says federal law is supreme 'any thing in the Constitution or Laws of any State to the contrary notwithstanding,' it means state law loses even if it says otherwise." },
  { term: "Nullification", definition: "The (rejected) idea that states can declare federal laws unconstitutional and refuse to enforce them. The Supreme Court has consistently ruled this invalid." },

  // === O ===
  { term: "Oath of Office", definition: "A solemn promise to uphold the Constitution, required of all government officials. The President's oath is specified in the Constitution. No religious test can be required." },
  { term: "Ordain and Establish", definition: "To officially create and put into effect. 'We the People...do ordain and establish this Constitution' means the people are creating and authorizing this system of government." },
  { term: "Original Intent", definition: "A method of interpreting the Constitution based on what its authors originally meant when they wrote it. Contrasted with 'living Constitution' approaches that allow meaning to evolve." },
  { term: "Original Jurisdiction", definition: "Cases a court hears first, before any appeals. The Supreme Court has original jurisdiction in cases involving states or ambassadors." },
  { term: "Overt Act", definition: "An open, observable action. Treason requires proof of an overt act, because just thinking about betraying the country isn't enough. Two witnesses must testify to the same overt act." },
  { term: "Override", definition: "To overrule or set aside. Congress can override a presidential veto with a 2/3 vote in both chambers, passing the bill into law despite the President's objection." },
  { term: "Overrule", definition: "When a higher court changes or rejects a legal principle from a previous case. When the Supreme Court overrules a precedent, the old rule no longer applies." },

  // === P ===
  { term: "Pardon", definition: "The President's power to forgive a federal crime, eliminating the punishment. Pardons cannot be used to undo impeachment. State governors can pardon state crimes." },
  { term: "Penumbra", definition: "An implied zone of protection. Justice Douglas argued that specific Bill of Rights guarantees have 'penumbras,' or implied protections that extend beyond their literal text, which create a right to privacy." },
  { term: "Peonage", definition: "A system of forced labor to pay off a debt. Essentially slavery through debt. Banned under the 13th Amendment and federal anti-peonage laws." },
  { term: "Peremptory Challenge", definition: "The right to reject a potential juror during jury selection without giving a reason. Lawyers for both sides get a limited number. Cannot be used to exclude jurors based on race or gender." },
  { term: "Petition", definition: "A formal request to the government. The 1st Amendment protects your right to 'petition the government for a redress of grievances,' meaning you can formally demand the government address problems." },
  { term: "Plaintiff", definition: "The person or entity who files a lawsuit. In civil cases, the plaintiff is suing for damages or other relief. In criminal cases, the government (not a private plaintiff) brings charges." },
  { term: "Plea Bargain", definition: "An agreement where the defendant pleads guilty to a lesser charge in exchange for a lighter sentence. About 95% of federal criminal cases are resolved this way." },
  { term: "Plurality", definition: "A court opinion that has the most votes but not a majority. Plurality opinions are not as strong as majority opinions in setting precedent but still guide future cases." },
  { term: "Police Power", definition: "The broad authority of state governments to pass laws protecting public health, safety, welfare, and morals. This is the source of most state regulations, from speed limits to building codes." },
  { term: "Political Question", definition: "An issue that courts refuse to decide because it is assigned to another branch of government. For example, courts won't review how the Senate conducts impeachment trials." },
  { term: "Poll Tax", definition: "A fee required to vote. Used historically to prevent poor people and Black citizens from voting. Banned for federal elections by the 24th Amendment and for all elections by the Supreme Court." },
  { term: "Popular Sovereignty", definition: "The principle that the government's power comes from the people. 'We the People' establishes this in the Constitution's first three words." },
  { term: "Posterity", definition: "Future generations. The Preamble says the Constitution is established to 'secure the blessings of liberty to ourselves and our posterity,' meaning for us and for all future Americans." },
  { term: "Precedent", definition: "A previous court decision that guides future cases with similar facts. Lower courts are bound by precedents set by higher courts." },
  { term: "Preclearance", definition: "A requirement that certain states get federal approval before changing their voting laws. Part of the Voting Rights Act, it was effectively ended when the Supreme Court struck down the coverage formula in Shelby County v. Holder." },
  { term: "Preemption", definition: "When federal law overrides or displaces state law on the same subject. Based on the Supremacy Clause. If Congress occupies a field of regulation, states generally cannot pass conflicting laws." },
  { term: "Presentment", definition: "A formal accusation of a crime issued by a grand jury on its own initiative (rather than at a prosecutor's request). The 5th Amendment mentions presentments alongside indictments." },
  { term: "Prior Restraint", definition: "Government censorship that blocks speech or publication before it happens. Courts have set an extremely high bar for prior restraint, making it almost always unconstitutional." },
  { term: "Privileges and Immunities", definition: "Rights and protections that come with citizenship. The 14th Amendment says states cannot abridge these. Article IV says states must extend them to citizens from other states." },
  { term: "Pro Forma Session", definition: "A brief Congressional session, sometimes lasting only seconds, held to technically remain 'in session.' Used to block the President from making recess appointments." },
  { term: "Probable Cause", definition: "Reasonable grounds to believe a crime has been committed. Required for arrests and search warrants under the 4th Amendment. More than a hunch, less than proof beyond a reasonable doubt." },
  { term: "Procedural Due Process", definition: "The requirement that the government follow fair procedures before depriving you of life, liberty, or property. This means notice of what you are accused of and a chance to be heard." },
  { term: "Prosecute", definition: "To bring criminal charges against someone and pursue a conviction in court. The government is the prosecutor in criminal cases." },
  { term: "Prudence", definition: "Careful good judgment. The Declaration says 'prudence will dictate that governments long established should not be changed for light and transient causes,' meaning you shouldn't overthrow government over small problems." },
  { term: "Public Forum", definition: "A government-owned space where people have a constitutional right to express themselves, such as public streets, sidewalks, and parks. The government can impose reasonable time, place, and manner restrictions but cannot ban speech entirely." },
  { term: "Pursuance", definition: "In accordance with or carrying out. The Supremacy Clause says laws made 'in pursuance' of the Constitution are the supreme law, meaning only constitutional federal laws override state laws." },

  // === Q ===
  { term: "Qualified Immunity", definition: "A legal shield that protects government officials from personal liability unless they violated 'clearly established' rights. Critics say it makes it nearly impossible to hold police and officials accountable for misconduct." },
  { term: "Quartering", definition: "Housing soldiers in private homes. The 3rd Amendment prohibits forced quartering of troops in peacetime." },
  { term: "Quorum", definition: "The minimum number of members who must be present for a legislative body to conduct business. In Congress, it's a majority of each chamber." },

  // === R ===
  { term: "Ratification", definition: "Formal approval. The Constitution required ratification by 9 of 13 states. Amendments require ratification by 3/4 of states (38 of 50)." },
  { term: "Reasonable Expectation of Privacy", definition: "The legal test for whether the 4th Amendment applies. If you have a subjective expectation of privacy that society recognizes as reasonable, the government generally needs a warrant to intrude." },
  { term: "Reasonable Suspicion", definition: "A lower standard than probable cause. Police need reasonable suspicion to briefly stop and question you (a 'Terry stop'), but need probable cause to arrest or search." },
  { term: "Recess Appointment", definition: "When the President fills a government position while the Senate is not in session, bypassing the normal confirmation process. The appointment is temporary." },
  { term: "Recuse", definition: "When a judge voluntarily steps aside from a case because of a conflict of interest or the appearance of bias." },
  { term: "Redress", definition: "A remedy or correction of a wrong. The 1st Amendment protects your right to petition the government for 'redress of grievances,' which means to demand that wrongs be made right." },
  { term: "Remand", definition: "When a higher court sends a case back to a lower court for further proceedings. The Supreme Court often remands cases with instructions on how to apply its ruling." },
  { term: "Repeal", definition: "To officially revoke or cancel a law. The 21st Amendment repealed the 18th Amendment (Prohibition). It is the only time an amendment has been repealed." },
  { term: "Reprieve", definition: "A temporary postponement of a sentence, especially a death sentence. The President has the power to grant reprieves for federal crimes." },
  { term: "Republican Form of Government", definition: "A government where power is held by the people and their elected representatives, rather than a king or dictator. The Constitution guarantees every state a republican form of government." },
  { term: "Reserved Powers", definition: "Powers that the Constitution does not give to the federal government and does not prohibit to the states. Under the 10th Amendment, these belong to the states or the people." },
  { term: "Retained", definition: "Kept or held onto. The 9th Amendment says rights 'retained by the people' are protected, so you keep all your natural rights, not just the ones listed." },
  { term: "Reverse", definition: "When a higher court overturns a lower court's decision. The opposite of 'affirm.'" },

  // === S ===
  { term: "Search Incident to Arrest", definition: "A warrantless search of a person and the area within their immediate reach during a lawful arrest. Police can search for weapons and evidence that might be destroyed, but not your entire home." },
  { term: "Section 1983", definition: "A federal law (42 U.S.C. Section 1983) that allows people to sue state and local officials for violating their constitutional rights. The primary tool for civil rights lawsuits against police and government officials." },
  { term: "Sedition", definition: "Speech or conduct that encourages rebellion against the government. The line between protected political dissent and illegal sedition has been debated throughout American history." },
  { term: "Seizure", definition: "When the government takes possession of a person or property. The 4th Amendment protects against 'unreasonable seizures.' Being detained by police is a seizure of your person." },
  { term: "Self-Evident", definition: "Obviously true without needing proof. The Declaration says 'we hold these truths to be self-evident, that all men are created equal.' These principles are so fundamental they don't require argument." },
  { term: "Self-Incrimination", definition: "Being forced to provide testimony or evidence that could be used against you in a criminal case. The 5th Amendment protects against compelled self-incrimination, which is where 'pleading the Fifth' comes from." },
  { term: "Separation of Powers", definition: "Dividing government into three branches: legislative (makes laws), executive (enforces laws), and judicial (interprets laws). Prevents any one branch from becoming too powerful." },
  { term: "Slander", definition: "A false spoken statement that damages someone's reputation. The spoken counterpart to libel (written defamation)." },
  { term: "Sovereign Immunity", definition: "The principle that the government cannot be sued without its consent. The 11th Amendment limits suits against states in federal court." },
  { term: "Standing", definition: "The legal right to bring a lawsuit. You must show you suffered a concrete injury caused by the defendant that a court can fix. Without standing, your case gets dismissed." },
  { term: "Standing Army", definition: "A permanent military force maintained in peacetime. The Founders feared standing armies as tools of tyranny. The Constitution requires Congress to re-authorize military funding every two years." },
  { term: "Stare Decisis", definition: "Latin for 'to stand by things decided.' The principle that courts should follow precedent and not overturn established rulings without strong reason. Provides stability and predictability in the law." },
  { term: "Statute", definition: "A law passed by a legislature (Congress or a state legislature). Different from case law, which comes from court decisions, or regulations, which come from government agencies." },
  { term: "Strict Scrutiny", definition: "The highest level of review courts apply when the government restricts a fundamental right or discriminates based on a suspect classification (like race). The government must prove a compelling interest and show its law is narrowly tailored." },
  { term: "Subpoena", definition: "A legal order requiring a person to appear in court or produce documents. From Latin 'sub poena' meaning 'under penalty.' Ignoring a subpoena can result in contempt of court." },
  { term: "Substance", definition: "In constitutional language, resources or wealth. The Declaration's complaint about officers sent 'to eat out their substance' means officials who drained the colonists' money and resources." },
  { term: "Substantive Due Process", definition: "The principle that certain rights are so fundamental that no process of law is sufficient to take them away. Courts use this to protect rights like privacy, marriage, and family that aren't explicitly in the Constitution." },
  { term: "Suffrage", definition: "The right to vote. The 15th, 19th, 24th, and 26th Amendments all expanded suffrage to different groups." },
  { term: "Suppress", definition: "To exclude evidence from a trial. If police obtained evidence through an unconstitutional search, a judge may 'suppress' it, meaning the jury never sees it." },
  { term: "Supremacy Clause", definition: "Article VI establishes the Constitution and valid federal law as 'the supreme law of the land.' State laws that conflict with federal law are overridden." },
  { term: "Symbolic Speech", definition: "Nonverbal expression that communicates a message, like burning a flag, wearing an armband, or kneeling during the national anthem. Protected by the 1st Amendment." },

  // === T ===
  { term: "Tender", definition: "A form of payment. The Constitution says states can only make gold and silver coin 'legal tender,' meaning acceptable for paying debts." },
  { term: "Testimony", definition: "A formal spoken statement, usually given under oath in court or before a legislative body. Giving false testimony is perjury, which is a crime." },
  { term: "Transient", definition: "Temporary or passing. The Declaration says governments 'should not be changed for light and transient causes,' meaning you shouldn't revolt over fleeting problems." },
  { term: "Treason", definition: "Betraying the United States by waging war against it or giving aid and comfort to its enemies. The Constitution defines it narrowly and requires two witnesses to the same overt act." },
  { term: "Treaty", definition: "A formal agreement between nations. The President negotiates treaties, but they must be approved by 2/3 of the Senate to take effect." },
  { term: "Tyranny", definition: "Cruel and oppressive government rule. The Founders designed the Constitution's separation of powers and checks and balances specifically to prevent tyranny." },

  // === U ===
  { term: "Unalienable", definition: "Cannot be taken away, surrendered, or transferred. The Declaration says rights to life, liberty, and the pursuit of happiness are unalienable. Also spelled 'inalienable.'" },
  { term: "Unconstitutional", definition: "In violation of the Constitution. Laws, executive orders, or government actions that conflict with the Constitution can be declared unconstitutional by courts and struck down." },
  { term: "Unenumerated Rights", definition: "Rights not specifically listed in the Constitution but still protected. The 9th Amendment says your rights aren't limited to what's written down." },
  { term: "Usurpation", definition: "Seizing power illegally or without authority. The Declaration describes a 'long train of abuses and usurpations,' meaning the King kept grabbing power that wasn't his." },

  // === V ===
  { term: "Vacate", definition: "To void or cancel a court decision. A higher court can vacate a lower court's ruling, effectively erasing it as if it never happened." },
  { term: "Venue", definition: "The geographic location where a trial takes place. The 6th Amendment guarantees trial in the district where the crime occurred." },
  { term: "Verdict", definition: "The jury's formal decision in a trial, specifically guilty or not guilty in criminal cases, or for/against the plaintiff in civil cases." },
  { term: "Vested", definition: "Placed in or given to. 'All legislative powers herein granted shall be vested in a Congress' means lawmaking authority is placed in Congress's hands." },
  { term: "Veto", definition: "The President's power to reject a bill passed by Congress. Congress can override a veto with a 2/3 vote in both chambers." },
  { term: "Void", definition: "Having no legal force. An unconstitutional law is void and is treated as if it never existed." },
  { term: "Voir Dire", definition: "The process of questioning potential jurors to determine if they can be fair and impartial. From Old French meaning 'to speak the truth.' Lawyers use this process to select (or reject) jurors." },

  // === W ===
  { term: "Waive", definition: "To voluntarily give up a right. You can waive your right to a jury trial, your right to remain silent, or other rights, but the waiver must be knowing, intelligent, and voluntary." },
  { term: "Warrant", definition: "A court order authorizing police to search a specific place or arrest a specific person. The 4th Amendment requires warrants be based on probable cause and describe specifics." },
  { term: "Well-Regulated", definition: "In 18th-century language, this meant 'properly functioning' or 'well-trained,' not 'heavily restricted by government rules.' The 2nd Amendment's 'well regulated militia' refers to a militia that is trained and disciplined." },
  { term: "Whistleblower", definition: "A person who reports illegal or unethical activity within an organization, especially a government agency. Various laws protect whistleblowers from retaliation." },
  { term: "Writ", definition: "A formal written court order commanding someone to do or stop doing something. Types include writs of habeas corpus, mandamus, and certiorari." }
];

